extern "C" unsigned int strlen(const char *);
extern "C" char *strcpy(char *, const char *);
void error(const char *, ...);

struct string_buf {
  unsigned long long *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx {
  friend stringx operator+(const stringx &, const stringx &);
  friend stringx operator+(const char *, const stringx &);
  friend stringx operator+(const stringx &, const char *);
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  stringx(const char *, int = -1);
  ~stringx();
  void append(const char *, int = -1);
  void append(const stringx &);
  void make_room(int);
  const char *c_str() const { return chars; }
};

inline stringx operator+(const stringx &lhs, const stringx &rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}
inline stringx operator+(const char *lhs, const stringx &rhs) {
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}
inline stringx operator+(const stringx &lhs, const char *rhs) {
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class chunk_flavor {
  char flavor[16];
public:
  chunk_flavor(const char *s = "UNREG") { strcpy(flavor, s); }
  bool operator==(const chunk_flavor &) const;
  bool operator!=(const chunk_flavor &cf) const { return !(*this == cf); }
  stringx to_stringx() const;
};

class chunk_file {
public:
  stringx get_name();
};

struct vector3d {
  float x, y, z;
  vector3d(float a, float b, float c) : x(a), y(b), z(c) {}
};
struct vector4d { float x, y, z, w; };
struct bounding_box {
  vector3d vmin;
  vector3d vmax;
  bounding_box()
    : vmin(3.402823466e+38F, 3.402823466e+38F, 3.402823466e+38F),
      vmax(-3.402823466e+38F, -3.402823466e+38F, -3.402823466e+38F) {}
};
struct convex_box {
  vector4d planes[6];
  bounding_box bbox;
};

extern const chunk_flavor CHUNK_END;
void serial_in(chunk_file &, chunk_flavor *);
void serial_in(chunk_file &, float *);

