void serial_in(chunk_file& fs, convex_box* box)
{
  chunk_flavor cf;

  for (serial_in(fs, &cf); cf != CHUNK_END; serial_in(fs, &cf)) {
    if (chunk_flavor("planes") == cf) {
      for (int i = 0; i < 6; i++) {
        vector4d plane;
        serial_in(fs, &plane.x);
        serial_in(fs, &plane.y);
        serial_in(fs, &plane.z);
        serial_in(fs, &plane.w);
        box->planes[i] = plane;
      }
    } else if (chunk_flavor("bbox") == cf) {
      bounding_box bbox;
      serial_in(fs, &bbox.vmin.x);
      serial_in(fs, &bbox.vmin.y);
      serial_in(fs, &bbox.vmin.z);
      serial_in(fs, &bbox.vmax.x);
      serial_in(fs, &bbox.vmax.y);
      serial_in(fs, &bbox.vmax.z);
      box->bbox = bbox;
    } else {
      stringx msg = stringx("unknown chunk type '") + cf.to_stringx() + "' in '" + fs.get_name();
      error(msg.c_str());
    }
  }
}
